package com.primehr.security;
import com.primehr.integration.administrative.*; import org.springframework.security.access.*; import org.springframework.stereotype.*;
@Component public class RspEvaluationPolicyPermissionGuard {public static final String FEATURE="primehr.rsp-evaluation-policy";private final AdministrativeAuthorizationClient client;public RspEvaluationPolicyPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public EffectiveFeaturePermission require(PrimeHrAction action,String token){return requireAgencyWide(client,FEATURE,action,token);}static EffectiveFeaturePermission requireAgencyWide(AdministrativeAuthorizationClient client,String feature,PrimeHrAction action,String token){if(token==null||!token.regionMatches(true,0,"Bearer ",0,7))throw new AccessDeniedException("A bearer token is required");EffectiveFeaturePermission p=client.resolve(feature,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case PUBLISH->p.canPublish();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();case ASSESS->p.canAssess();case VALIDATE->p.canValidate();case FINALIZE->p.canFinalize();case ARCHIVE->p.canDelete();};if(!allowed||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("The required agency-wide PrimeHR permission is not granted");return p;}}
